const data = { user: { posts: [{ title: "Hello" }] } }
const title = data && data.user && data.user.posts && data.user.posts[0] && data.user.posts[0].title || "No title"
const author = data && data.user && data.user.author && data.user.author.name || "Unknown"
return { title, author }
